simple_computer(x, n)
{
  int sum=0;
  for (int i=0; i<n; i++)
      sum+=2*i*x[i];
  return sum;
}

compute(M, N, x, y){
  int a = 0, b = 0;
  for (i = 0; i < N; i++) { a = a + y[i]; }
  for (j = 0; j < M; j++) { b = b + x[j]; }
}

int maximum(int a[], int n) {
  int i, max = a[0];
  for (i = 1; i < n; i++)
    if (a[i] > max) max = a[i];
  return max;
}

for (i=0; i<n; i++)
  a[i] = i;
for (i=0; i<n; i++)
  for (j=0; j<n; j++)
    a[i] += a[j]+j*2;

int power(int x, int n){
  if(n == 0) return 1;
  if(n == 1) return x;
  return x * power(x, n-1);
}

int suma = 0;
for (int i = 1; i <= n; ++i)
    suma = suma*i + i;
return suma;
